def comps(g, col):
    h,w=len(g),len(g[0]); seen=set(); out=[]
    for r in range(h):
        for c in range(w):
            if g[r][c]==col and (r,c) not in seen:
                st=[(r,c)]; seen.add((r,c)); cc=[]
                while st:
                    y,x=st.pop(); cc.append((y,x))
                    for dy,dx in((1,0),(-1,0),(0,1),(0,-1)):
                        ny,nx=y+dy,x+dx
                        if 0<=ny<h and 0<=nx<w and g[ny][nx]==col and (ny,nx) not in seen:
                            seen.add((ny,nx)); st.append((ny,nx))
                out.append(cc)
    return out

def transform(g):
    g=[row[:] for row in g]; h,w=len(g),len(g[0])
    cols=set(x for row in g for x in row if x)
    for col in cols:
        cs=comps(g,col)
        if len(cs)!=4: continue
        cells=[p for cc in cs for p in cc]
        for a in cells:
            for b in cells:
                if a<b:
                    (r1,c1),(r2,c2)=a,b
                    if r1==r2:
                        for c in range(min(c1,c2)+1,max(c1,c2)):
                            if g[r1][c]==0: g[r1][c]=col
                    if c1==c2:
                        for r in range(min(r1,r2)+1,max(r1,r2)):
                            if g[r][c1]==0: g[r][c1]=col
    return g

